compact/powershell/opencode/ollama-embed.copy:
# Keep generated configuration files out of version control.
if (-not (Test-Path .gitignore)) { New-Item -ItemType File -Path .gitignore | Out-Null }
Add-Content -Path .gitignore -Value '.chunkhound.json'
# Configure ChunkHound with Ollama embeddings and Requesty for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
# You'll need: Requesty API key
@'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "requesty",
    "model": "deepseek/deepseek-v4.1-flash",
    "api_key": "<YOUR_REQUESTY_API_KEY>"
  }
}
'@ | Set-Content -Path '.chunkhound.json' -Encoding utf8
# Configure OpenCode to connect to ChunkHound via MCP.
if (Test-Path 'opencode.json') {
Write-Host @'
opencode.json already exists — merge this block into it manually:
{
  "mcp": {
    "ChunkHound": {
      "type": "local",
      "command": [
        "chunkhound",
        "mcp"
      ]
    }
  }
}
'@
} else {
@'
{
  "mcp": {
    "ChunkHound": {
      "type": "local",
      "command": [
        "chunkhound",
        "mcp"
      ]
    }
  }
}
'@ | Set-Content -Path 'opencode.json' -Encoding utf8
}
# Build ChunkHound's search index for this project.
chunkhound index .

